170	  /**
171	   * Returns every link in the text that would break on GitHub, CurseForge or Modrinth. Relative
172	   * links and links into this repo must name a file or folder in the git index, with the exact
173	   * case, because GitHub paths are case-sensitive while the macOS file system is not. A link into
174	   * the repo must also use the julian-perge owner and the main branch, since that is what the
175	   * published page loads.
176	   */
177	  private static List<String> brokenLinks(Path doc, String text, Set<String> tracked) {
178	    List<String> broken = new ArrayList<>();
179	    for (String target : targets(text)) {
180	      if (target.startsWith("http://")
181	          || target.startsWith("https://")
182	          || target.startsWith("#")
183	          || target.startsWith("mailto:")) {
184	        continue;
185	      }
186	      Path base = doc.getParent() == null ? Path.of("") : doc.getParent();
187	      String path = base.resolve(target.replaceFirst("#.*$", "")).normalize().toString();
188	      if (!isTracked(path, tracked)) {
189	        broken.add(target);
190	      }
191	    }
192	    Matcher url = GITHUB_URL.matcher(text);
193	    while (url.find()) {
194	      String owner = url.group(2);
195	      String repo = url.group(3);
196	      String rest = url.group(4);
197	      if (!repo.equalsIgnoreCase("ModularPlanters")) {
198	        continue;
199	      }
200	      if (!owner.equals("julian-perge") || !repo.equals("ModularPlanters")) {
201	        broken.add(url.group());
202	        continue;
203	      }
204	      String branchAndPath;
205	      if (url.group(1).startsWith("raw.")) {
206	        branchAndPath = rest;
207	      } else if (rest.startsWith("blob/") || rest.startsWith("tree/")) {
208	        branchAndPath = rest.substring("blob/".length());
209	      } else {
210	        continue;
211	      }
212	      if (!branchAndPath.startsWith("main/")
213	          || !isTracked(branchAndPath.substring("main/".length()), tracked)) {
214	        broken.add(url.group());
215	      }
216	    }
217	    return broken;
218	  }
219	
220	  private static boolean isTracked(String path, Set<String> tracked) {
221	    String file = path.replaceFirst("/$", "");
222	    return tracked.contains(file)
223	        || tracked.stream().anyMatch(entry -> entry.startsWith(file + "/"));
224	  }
225	
226	  /**
227	   * Returns the files git tracks in the folder, or nothing when the folder isn't a git clone or git
228	   * isn't installed, as with source downloaded as a zip. The link check then skips instead of
229	   * failing the build.
230	   */
231	  private static Optional<Set<String>> trackedFiles(Path dir) throws InterruptedException {
232	    try {
233	      Process git =
234	          new ProcessBuilder("git", "ls-files")
235	              .directory(dir.toFile())
236	              .redirectErrorStream(true)
237	              .start();
238	      String output = new String(git.getInputStream().readAllBytes());
239	      if (git.waitFor() != 0) {
240	        return Optional.empty();
241	      }
242	      return Optional.of(new TreeSet<>(Arrays.asList(output.split("\n"))));
243	    } catch (IOException e) {
244	      return Optional.empty();
245	    }
246	  }
247	
248	  private static List<String> targets(String text) {
249	    List<String> targets = new ArrayList<>();
250	    for (Pattern pattern : List.of(MARKDOWN_TARGET, HTML_TARGET)) {
251	      Matcher matcher = pattern.matcher(text);
252	      while (matcher.find()) {
253	        targets.add(matcher.group(1));
254	      }
255	    }
256	    return targets;
257	  }
258	
