18	public final class OutputSink {
19	  private final List<ExportBlockEntity> blocks;
20	  private final @Nullable MeLink me;
21	  private final Runnable onStale;
22	  private final ResourceHandler<ItemResource> allBlocks;
23	  private final ResourceHandler<ItemResource> extractView =
24	      new DelegatingResourceHandler<>(this::liveHandler);
25	
26	  public OutputSink(List<ExportBlockEntity> inOrder, @Nullable MeLink me, Runnable onStale) {
27	    this.blocks = List.copyOf(inOrder);
28	    this.me = me;
29	    this.onStale = onStale;
30	    this.allBlocks =
31	        new CombinedResourceHandler<>(
32	            blocks.stream().map(ExportBlockEntity::externalHandler).toList());
33	  }
34	
35	  private List<ExportBlockEntity> live() {
36	    return LiveBlocks.of(blocks, onStale);
37	  }
38	
39	  boolean allLive() {
40	    return LiveBlocks.allLive(blocks, onStale);
41	  }
42	
43	  // A combined handler fixes its slot count when it is built, so a removed block needs a new one
44	  // until the core rebuilds the pool.
45	  private ResourceHandler<ItemResource> liveHandler() {
46	    return allLive()
47	        ? allBlocks
48	        : new CombinedResourceHandler<>(
49	            live().stream().map(ExportBlockEntity::externalHandler).toList());
50	  }
51	
52	  private @Nullable MeLink liveMe() {
53	    if (me == null) {
54	      return null;
55	    }
56	    if (me.isRemoved()) {
57	      onStale.run();
58	      return null;
59	    }
60	    return me;
61	  }
62	
63	  public boolean hasRoomFor(List<ItemStack> stacks) {
64	    int[] remaining = new int[stacks.size()];
65	    for (int i = 0; i < stacks.size(); i++) {
66	      ItemStack stack = stacks.get(i);
67	      remaining[i] =
68	          stack.isEmpty()
69	              ? 0
70	              : stack.getCount() - meTakes(ItemResource.of(stack), stack.getCount(), true);
71	    }
72	    try (Transaction tx = Transaction.openRoot()) {
73	      // ME is asked about each stack on its own and keeps nothing, so stacks that share ME room can
74	      // both pass, and the part ME refuses later goes to the export blocks or is held in the
75	      // planter block.
76	      for (int i = 0; i < stacks.size(); i++) {
77	        if (remaining[i] > 0
78	            && insertIntoBlocks(ItemResource.of(stacks.get(i)), remaining[i], tx) < remaining[i]) {
79	          return false;
80	        }
81	      }
82	      return true;
83	    }
84	  }
85	
86	  public ItemStack insert(ItemStack stack) {
87	    if (stack.isEmpty()) {
88	      return ItemStack.EMPTY;
89	    }
90	    ItemResource resource = ItemResource.of(stack);
91	    int remaining = stack.getCount() - meTakes(resource, stack.getCount(), false);
92	    remaining -= insertIntoBlocks(resource, remaining, null);
93	    return remaining == 0 ? ItemStack.EMPTY : resource.toStack(remaining);
94	  }
95	
96	  public ResourceHandler<ItemResource> extractView() {
97	    return extractView;
98	  }
