100	  // ME calls must happen with no transaction open, so each slot gives up what ME says it will take
101	  // in one committed transaction, offers that to ME, and puts what ME refused back into the same
102	  // slot in a second one.
103	  public void moveExportsInto(MeLink me) {
104	    if (!me.online()) {
105	      return;
106	    }
107	    for (ExportBlockEntity block : live()) {
108	      ItemStacksResourceHandler storage = block.storage();
109	      for (int slot = 0; slot < storage.size(); slot++) {
110	        ItemResource resource = storage.getResource(slot);
111	        if (resource.isEmpty()) {
112	          continue;
113	        }
114	        int asked = (int) me.insertItem(resource, storage.getAmountAsInt(slot), true);
115	        if (asked == 0) {
116	          continue;
117	        }
118	        int taken;
119	        try (Transaction tx = Transaction.openRoot()) {
120	          taken = storage.extract(slot, resource, asked, tx);
121	          tx.commit();
122	        }
123	        int refused = taken - (int) me.insertItem(resource, taken, false);
124	        if (refused == 0) {
125	          continue;
126	        }
127	        int returned;
128	        try (Transaction tx = Transaction.openRoot()) {
129	          returned = storage.insert(slot, resource, refused, tx);
130	          tx.commit();
131	        }
132	        // The put-back fits because the slot just gave up at least that much of the same item and
133	        // nothing else writes to it during the ME call, so dropping the rest at the block only
134	        // keeps the items if another mod breaks that.
135	        if (returned < refused) {
136	          ItemStack lost = resource.toStack(refused - returned);
137	          BlockPos pos = block.getBlockPos();
138	          while (!lost.isEmpty()) {
139	            Containers.dropItemStack(
140	                block.getLevel(),
141	                pos.getX(),
142	                pos.getY(),
143	                pos.getZ(),
144	                lost.split(lost.getMaxStackSize()));
145	          }
146	        }
147	      }
148	    }
149	  }
150	
151	  public int fillPercent() {
152	    long stored = 0;
153	    long capacity = 0;
154	    for (ExportBlockEntity block : live()) {
155	      ItemStacksResourceHandler storage = block.storage();
156	      for (int slot = 0; slot < storage.size(); slot++) {
157	        stored += storage.getAmountAsLong(slot);
158	        capacity += storage.getCapacityAsLong(slot, storage.getResource(slot));
159	      }
160	    }
161	    return capacity == 0 ? 0 : (int) (stored * 100 / capacity);
162	  }
163	
164	  private int meTakes(ItemResource resource, int amount, boolean simulate) {
165	    MeLink link = liveMe();
166	    return link != null && link.online() ? (int) link.insertItem(resource, amount, simulate) : 0;
167	  }
168	
169	  private int insertIntoBlocks(
170	      ItemResource resource, int amount, @Nullable TransactionContext transaction) {
171	    int inserted = 0;
172	    for (ExportBlockEntity block : live()) {
173	      if (inserted == amount) {
174	        break;
175	      }
176	      inserted +=
177	          ResourceHandlerUtil.insertStacking(
178	              block.storage(), resource, amount - inserted, transaction);
179	    }
180	    return inserted;
181	  }
182	}
