115	    }
116	    ItemResource filter = me.fertilizerFilter();
117	    if (AteBridge.fertilizer(filter) == null) {
118	      return;
119	    }
120	    List<FertilizerBlockEntity> live = live();
121	    int room;
122	    // The transaction is never committed, so measuring the room leaves the storage as it was.
123	    try (Transaction tx = Transaction.openRoot()) {
124	      room = insertInto(live, filter, Integer.MAX_VALUE, tx);
125	    }
126	    if (room == 0) {
127	      return;
128	    }
129	    int taken = (int) me.extractItem(filter, room, false);
130	    if (taken == 0) {
131	      return;
132	    }
133	    int inserted;
134	    try (Transaction tx = Transaction.openRoot()) {
135	      inserted = insertInto(live, filter, taken, tx);
136	      tx.commit();
137	    }
138	    // The insert fits because the room was measured just before and the ME call in between adds
139	    // nothing to these blocks, so returning the rest to ME and dropping what ME refuses at the
140	    // first block only keeps the items if another mod breaks that.
141	    if (inserted < taken) {
142	      int left = taken - inserted - (int) me.insertItem(filter, taken - inserted, false);
143	      ItemStack lost = filter.toStack(left);
144	      BlockPos pos = live.getFirst().getBlockPos();
145	      while (!lost.isEmpty()) {
146	        Containers.dropItemStack(
147	            live.getFirst().getLevel(),
148	            pos.getX(),
149	            pos.getY(),
150	            pos.getZ(),
151	            lost.split(lost.getMaxStackSize()));
152	      }
153	    }
154	  }
155	
156	  private static int insertInto(
157	      List<FertilizerBlockEntity> blocks,
158	      ItemResource resource,
159	      int amount,
160	      TransactionContext transaction) {
161	    int inserted = 0;
162	    for (FertilizerBlockEntity block : blocks) {
163	      if (inserted == amount) {
164	        break;
165	      }
166	      inserted +=
167	          ResourceHandlerUtil.insertStacking(
168	              block.storage(), resource, amount - inserted, transaction);
169	    }
170	    return inserted;
171	  }
172	
173	  public Budget budget() {
174	    FertilizerData data = data();
175	    return new Budget(this, data, data == null ? 0 : available());
176	  }
177	
178	  // Every planter block of a core claims from one budget per tick, in the position order the core
179	  // ticks them, so claims never add up to more than the pool held when the tick started, and a
180	  // claim takes items only when its group harvests, one per seed.
181	  public static final class Budget {
182	    private final FertilizerPool pool;
183	    private final @Nullable FertilizerData data;
184	    private int unclaimed;
185	
186	    private Budget(FertilizerPool pool, @Nullable FertilizerData data, int unclaimed) {
187	      this.pool = pool;
188	      this.data = data;
189	      this.unclaimed = unclaimed;
190	    }
191	
192	    public @Nullable FertilizerData claim(int seeds) {
193	      if (data == null || seeds > unclaimed) {
194	        return null;
195	      }
196	      unclaimed -= seeds;
197	      return data;
198	    }
199	
200	    public void consume(int count) {
201	      pool.consume(count);
202	    }
203	  }
204	}
