1	package io.github.julianperge.modular_planters.multiblock;
2	
3	import io.github.julianperge.modular_planters.blockentity.PowerBlockEntity;
4	import java.util.List;
5	import net.neoforged.neoforge.transfer.energy.EnergyHandler;
6	import net.neoforged.neoforge.transfer.transaction.TransactionContext;
7	
8	public final class PowerPool {
9	  private final List<PowerBlockEntity> blocks;
10	  private final Runnable onStale;
11	  private final EnergyHandler insertView = new InsertView();
12	
13	  public PowerPool(List<PowerBlockEntity> inOrder, Runnable onStale) {
14	    this.blocks = List.copyOf(inOrder);
15	    this.onStale = onStale;
16	  }
17	
18	  private List<PowerBlockEntity> live() {
19	    return LiveBlocks.of(blocks, onStale);
20	  }
21	
22	  public long stored() {
23	    long total = 0;
24	    for (PowerBlockEntity block : live()) {
25	      total += block.stored();
26	    }
27	    return total;
28	  }
29	
30	  public long capacity() {
31	    long total = 0;
32	    for (PowerBlockEntity block : live()) {
33	      total += block.capacity();
34	    }
35	    return total;
36	  }
37	
38	  public boolean tryTake(long amount) {
39	    if (amount < 0 || stored() < amount) {
40	      return false;
41	    }
42	    long remaining = amount;
43	    for (PowerBlockEntity block : live()) {
44	      int taken = (int) Math.min(remaining, block.stored());
45	      if (taken > 0) {
46	        block.setStored(block.stored() - taken);
47	        remaining -= taken;
48	      }
49	    }
50	    return true;
51	  }
52	
53	  public long refillFrom(MeLink me) {
54	    if (!me.online()) {
55	      return 0;
56	    }
57	    List<PowerBlockEntity> live = live();
58	    long room = 0;
59	    // A power block can hold more than its capacity after the config lowers the cap, so each
60	    // block's free room is floored at zero here and below.
61	    for (PowerBlockEntity block : live) {
62	      room += Math.max(0, block.capacity() - block.stored());
63	    }
64	    if (room == 0) {
65	      return 0;
66	    }
67	    long moved = me.extractEnergy(room, false);
68	    long remaining = moved;
69	    for (PowerBlockEntity block : live) {
70	      int added = (int) Math.min(remaining, Math.max(0, block.capacity() - block.stored()));
71	      if (added > 0) {
72	        block.setStored(block.stored() + added);
73	        remaining -= added;
74	      }
75	    }
76	    return moved;
77	  }
78	
79	  public EnergyHandler insertView() {
80	    return insertView;
81	  }
82	
83	  private final class InsertView implements EnergyHandler {
84	    @Override
85	    public long getAmountAsLong() {
86	      return stored();
87	    }
88	
89	    @Override
90	    public long getCapacityAsLong() {
91	      return capacity();
92	    }
93	
94	    @Override
95	    public int insert(int amount, TransactionContext transaction) {
96	      int inserted = 0;
97	      for (PowerBlockEntity block : live()) {
98	        if (inserted == amount) {
99	          break;
100	        }
101	        inserted += block.externalHandler().insert(amount - inserted, transaction);
102	      }
103	      return inserted;
104	    }
105	
106	    @Override
107	    public int extract(int amount, TransactionContext transaction) {
108	      return 0;
109	    }
110	  }
111	}
