51	  // A planter block holds at most what one harvest of one group did not fit, so this allows 256
52	  // full stacks for each of a group's 64 seeds, far more than any recipe and harvest event add.
53	  private static final int HELD_OUTPUTS_CAP = SeedBin.CAPACITY * 256;
