1	package io.github.julianperge.modular_planters.logic;
2	
3	import java.util.List;
4	import java.util.function.ToIntFunction;
5	
6	public final class PlanterTicker {
7	  private PlanterTicker() {}
8	
9	  public record AdvanceResult(long energyUsed, boolean pausedForPower) {}
10	
11	  // A planter short on power advances no seed and asks for no growth time that tick, because the
12	  // Advanced Planter takes its energy before it posts the processing time event, but the caller
13	  // still harvests the seeds that were already ready.
14	  public static <S> AdvanceResult advance(
15	      SeedBin<S> bin,
16	      List<Group> groups,
17	      ToIntFunction<Group> growthTime,
18	      ToIntFunction<UpgradeSet> powerPerSeed,
19	      long energyAvailable) {
20	    long draw = 0;
21	    for (Group group : groups) {
22	      if (!bin.ready(group.first())) {
23	        draw += (long) group.size() * powerPerSeed.applyAsInt(group.upgrades());
24	      }
25	    }
26	    if (draw > energyAvailable) {
27	      return new AdvanceResult(0, true);
28	    }
29	    for (Group group : groups) {
30	      if (bin.ready(group.first())) {
31	        continue;
32	      }
33	      int time = growthTime.applyAsInt(group);
34	      for (int seed : group.seeds()) {
35	        bin.advance(seed);
36	        if (bin.progress(seed) >= time) {
37	          bin.markReady(seed);
38	        }
39	      }
40	    }
41	    return new AdvanceResult(draw, false);
42	  }
43	}
