1	package io.github.julianperge.modular_planters.multiblock;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	import net.minecraft.world.level.block.entity.BlockEntity;
6	
7	final class LiveBlocks {
8	  private LiveBlocks() {}
9	
10	  // A pool is only rebuilt when the core's scan changes, so a block broken or unloaded since then
11	  // is still listed.
12	  // This returns only the blocks that are not removed and asks the core to rescan when it finds a
13	  // removed one.
14	  static <T extends BlockEntity> List<T> of(List<T> blocks, Runnable onStale) {
15	    List<T> live = new ArrayList<>(blocks.size());
16	    boolean stale = false;
17	    for (T block : blocks) {
18	      if (block.isRemoved()) {
19	        stale = true;
20	      } else {
21	        live.add(block);
22	      }
23	    }
24	    if (stale) {
25	      onStale.run();
26	    }
27	    return live;
28	  }
29	
30	  // This is the check of() makes, without building a list, for handlers that are asked on every
31	  // transfer.
32	  static <T extends BlockEntity> boolean allLive(List<T> blocks, Runnable onStale) {
33	    for (T block : blocks) {
34	      if (block.isRemoved()) {
35	        onStale.run();
36	        return false;
37	      }
38	    }
39	    return true;
40	  }
41	}
