# /// script
# requires-python = ">=3.13"
# dependencies = ["markdown>=3.7,<4"]
# ///
import base64, re, sys
from pathlib import Path
import markdown
d = Path(sys.argv[1]); repo = Path(sys.argv[2]); out = Path(sys.argv[3])
RAW = "https://raw.githubusercontent.com/julian-perge/ModularPlanters/main/docs/media/"
def render(md_text, media):
    html = markdown.markdown(md_text)
    def sub(m):
        name = m.group(1); data = (media / name).read_bytes()
        mime = "image/jpeg" if name.endswith(".jpg") else "image/png"
        return 'src="data:%s;base64,%s" loading="lazy"' % (mime, base64.b64encode(data).decode())
    return re.sub(r'src="' + re.escape(RAW) + r'([^"]+)"', sub, html)
old = render((d / "old/description.md").read_text(), d / "old")
new = render((repo / "docs/description.md").read_text(), repo / "docs/media")
tpl = Path(sys.argv[4]).read_text()
out.write_text(tpl.replace("{{OLD}}", old).replace("{{NEW}}", new))
print(out, out.stat().st_size)
EOF
